// Helper to determine exact flight space left in Metric Tons (MT)
export const getAvailableFlightSpaceMT = (item) => {
  if (!item) return 18.0;
  if (item.spaceAvailableMT) return item.spaceAvailableMT;
  
  const airlineCapacityMap = {
    'SOL': 18.0, // Solit Air B737-400F Dedicated Freighter
    'QR': 26.5,  // Qatar Airways Cargo B777F
    'KQ': 20.0,  // Kenya Airways B787 / B737-800F
    'EK': 24.0,  // Emirates SkyCargo B777F
    'SV': 19.5,  // Saudia Cargo B777F
    'KL': 28.0,  // KLM Cargo B747-400ERF / B777F
    'AF': 22.0,  // Air France Cargo B777F
    'AI': 15.0,  // Air India B777-300ER Belly Hold
    'ET': 27.0,  // Ethiopian Airlines Cargo B777F
    'SN': 16.0,  // Brussels Airlines A330-300 Cargo Hold
    'FX': 25.0,  // FedEx Express B777F
    'DH': 24.5   // DHL Aviation B777F / B767F
  };

  const base = airlineCapacityMap[item.airlineId] || 18.0;
  const charCode = (item.id || '').charCodeAt(item.id.length - 1) || 0;
  const variance = ((charCode % 5) - 2) * 0.8;
  return Number(Math.max(4.0, base + variance).toFixed(1));
};
